
"use client";

import { useState } from "react";

export default function Home() {
  // Stores the story idea entered by the user.
  const [prompt, setPrompt] = useState("");

  // Stores the selected age range.
  const [ageRange, setAgeRange] = useState("3-5");

  // Stores the story generated by the AI.
  const [story, setStory] = useState("");

  // Stores error messages.
  const [error, setError] = useState("");

  // Tracks whether a story is being generated.
  const [loading, setLoading] = useState(false);

  // Sends the user's story idea to the backend.
  async function handleSubmit(
    event: React.FormEvent<HTMLFormElement>
  ) {
    event.preventDefault();

    // Clear previous results.
    setStory("");
    setError("");
    setLoading(true);

    try {
      // Send the request to the FastAPI backend.
      const response = await fetch(
        "http://127.0.0.1:8000/api/story-request",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            prompt: prompt,
            age_range: ageRange,
          }),
        }
      );

      // Read the backend response.
      const data = await response.json();

      // Display an error if the request failed.
      if (!response.ok) {
        setError(
          typeof data.detail === "string"
            ? data.detail
            : "Story generation failed. Please try again."
        );
        return;
      }

      // Display the actual story returned by the AI.
      const generatedStory = data.story || data.message;

      if (
        typeof generatedStory !== "string" ||
        !generatedStory.trim()
      ) {
        setError("The AI did not return a story. Please try again.");
        return;
      }

      setStory(generatedStory);
    } catch {
      // Handle connection problems.
      setError(
        "Could not connect to the backend. Please check that it is running."
      );
    } finally {
      // Stop the loading indicator.
      setLoading(false);
    }
  }

  return (
    <main
      style={{
        maxWidth: "700px",
        margin: "60px auto",
        padding: "24px",
        fontFamily: "Arial, sans-serif",
      }}
    >
      <h1>AI Storybook Builder 📚</h1>

      <p>
        Turn your imagination into a wonderful story!
      </p>

      {/* Form for entering a story idea. */}
      <form onSubmit={handleSubmit}>
        <label htmlFor="prompt">
          What should your story be about?
        </label>

        <textarea
          id="prompt"
          value={prompt}
          onChange={(event) => setPrompt(event.target.value)}
          placeholder="A little rabbit learns to share..."
          required
          minLength={3}
          maxLength={1000}
          rows={4}
          style={{
            display: "block",
            width: "100%",
            boxSizing: "border-box",
            margin: "10px 0 20px",
            padding: "12px",
            borderRadius: "8px",
            fontSize: "16px",
          }}
        />

        <label htmlFor="ageRange">
          Choose an age range
        </label>

        <select
          id="ageRange"
          value={ageRange}
          onChange={(event) => setAgeRange(event.target.value)}
          style={{
            display: "block",
            margin: "10px 0 20px",
            padding: "10px",
            borderRadius: "8px",
            fontSize: "16px",
          }}
        >
          <option value="3-5">Ages 3–5</option>
          <option value="6-8">Ages 6–8</option>
          <option value="9-12">Ages 9–12</option>
        </select>

        {/* Prevent multiple submissions while generating. */}
        <button
          type="submit"
          disabled={loading}
          style={{
            padding: "12px 20px",
            borderRadius: "8px",
            border: "none",
            cursor: loading ? "wait" : "pointer",
            fontSize: "16px",
            opacity: loading ? 0.7 : 1,
          }}
        >
          {loading ? "Creating your story..." : "Generate My Story ✨"}
        </button>
      </form>

      {/* Show a loading message while the AI works. */}
      {loading && (
        <p role="status">
          ✨ Our AI storyteller is creating your story. Please wait...
        </p>
      )}

      {/* Show an error if something goes wrong. */}
      {error && (
        <p
          role="alert"
          style={{
            marginTop: "20px",
            color: "#b91c1c",
          }}
        >
          {error}
        </p>
      )}

      {/* Display the completed AI-generated story. */}
      {story && (
        <section
          aria-live="polite"
          style={{
            marginTop: "32px",
            padding: "24px",
            border: "1px solid #e5d7a8",
            borderRadius: "14px",
            backgroundColor: "#fffdf5",
            color: "#333333",
            overflowWrap: "anywhere",
          }}
        >
          <h2>Your AI-Generated Story 📖</h2>

          <div
            style={{
              whiteSpace: "pre-wrap",
              lineHeight: 1.8,
              fontSize: "16px",
            }}
          >
            {story}
          </div>
        </section>
      )}
    </main>
  );
}
